// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

interface ISignatureModelRegistry {
    function getModelOwner(uint256 _id) external view returns (address);
}

/**
 * @title SignatureGatedProvenanceTracker
 * @notice Signature-gated variant of the verifier-gated write path.
 *
 *  The admission gate is an EIP-712 typed-data signature produced by the
 *  publisher instead of a Groth16 proof. It serves two purposes:
 *
 *   (1) Lower-cost comparator for the gating primitive (editor comment 2).
 *   (2) User-generated authorisation, so the on-chain owner is the recovered
 *       signer rather than a value asserted by the relay (editor comment 5).
 *
 *  The record layout, hash-linked chaining and statement-hash derivation are
 *  IDENTICAL to ZKProvenanceTracker so that gas figures are comparable.
 */
contract SignatureGatedProvenanceTracker is EIP712 {
    using ECDSA for bytes32;

    // Keep numeric event codes aligned with ZKProvenanceTracker so the
    // three-way experiment uses the same lifecycle state progression.
    enum EventType {
        REGISTERED,
        ACTIVATED,
        UPDATED,
        DEPRECATED,
        REVOKED,
        VERSION_RELEASED,
        TRANSFERRED,
        STAKED,
        UNSTAKED,
        SLASHED,
        ZK_PROOF_VERIFIED
    }

    struct ProvenanceRecord {
        uint256 recordId;
        uint256 modelId;
        EventType eventType;
        string ipfsMetadata;
        uint256 timestamp;
        address operator;
        bytes32 previousHash;
        bytes32 recordHash;
    }

    uint256 internal constant SNARK_SCALAR_FIELD =
        21888242871839275222246405745257275088548364400416034343698204186575808495617;

    // ProvenanceSubmission binds the model, the statement derived from the
    // canonical metadata, the event type, and a one-time nonce. The nonce plays
    // the role the nullifier plays in the proof-gated path.
    bytes32 private constant SUBMISSION_TYPEHASH = keccak256(
        "ProvenanceSubmission(uint256 modelId,uint8 eventType,uint256 statementHash,uint256 nonce)"
    );

    uint256 private _recordCounter;

    mapping(uint256 => ProvenanceRecord) public records;
    mapping(uint256 => uint256[]) public modelHistory;
    mapping(uint256 => bytes32) public modelChainHead;
    mapping(uint256 => bool) public modelBlacklist;
    mapping(uint256 => bool) public nonceUsed;

    ISignatureModelRegistry public immutable registry;

    event RecordAdded(uint256 indexed recordId, uint256 indexed modelId, EventType eventType, address indexed operator);
    event SubmissionAuthorised(uint256 indexed modelId, address indexed signer, uint256 nonce, uint256 statementHash);

    error ModelIsBlacklisted();
    error NonceAlreadyUsed();
    error UnauthorisedSigner();
    error ModelNotRegistered();

    constructor(address _registry) EIP712("ModelProvenance", "1") {
        require(_registry != address(0), "registry required");
        registry = ISignatureModelRegistry(_registry);
    }

    /**
     * @notice Admit a provenance record only if accompanied by a valid
     *         publisher signature over this exact submission.
     * @dev The relay may submit the transaction, but the recorded operator is
     *      the recovered signer, so a compromised relay cannot mis-assign it.
     */
    function addSignedRecord(
        uint256 _modelId,
        EventType _eventType,
        string calldata _canonicalMetadata,
        uint256 _nonce,
        bytes calldata _signature
    ) external returns (uint256) {
        if (modelBlacklist[_modelId]) revert ModelIsBlacklisted();

        address publisher = registry.getModelOwner(_modelId);
        if (publisher == address(0)) revert ModelNotRegistered();

        // Statement hash recomputed on-chain from the metadata being stored.
        uint256 statementHash = _statementHash(_canonicalMetadata);

        if (nonceUsed[_nonce]) revert NonceAlreadyUsed();

        bytes32 digest = _hashTypedDataV4(
            keccak256(abi.encode(SUBMISSION_TYPEHASH, _modelId, uint8(_eventType), statementHash, _nonce))
        );
        address signer = digest.recover(_signature);
        if (signer != publisher) revert UnauthorisedSigner();

        nonceUsed[_nonce] = true;
        emit SubmissionAuthorised(_modelId, signer, _nonce, statementHash);

        // Operator is the authenticated signer, NOT msg.sender (the relay).
        return _appendRecord(_modelId, _eventType, signer, _canonicalMetadata);
    }

    function _appendRecord(
        uint256 _modelId,
        EventType _eventType,
        address _operator,
        string memory _ipfsMetadata
    ) internal returns (uint256) {
        uint256 recordId = ++_recordCounter;
        bytes32 prevHash = modelChainHead[_modelId];

        ProvenanceRecord memory record = ProvenanceRecord({
            recordId: recordId,
            modelId: _modelId,
            eventType: _eventType,
            ipfsMetadata: _ipfsMetadata,
            timestamp: block.timestamp,
            operator: _operator,
            previousHash: prevHash,
            recordHash: bytes32(0)
        });

        record.recordHash = keccak256(
            abi.encode(
                record.recordId, record.modelId, record.eventType, record.ipfsMetadata,
                record.timestamp, record.operator, record.previousHash
            )
        );

        records[recordId] = record;
        modelHistory[_modelId].push(recordId);
        modelChainHead[_modelId] = record.recordHash;

        emit RecordAdded(recordId, _modelId, _eventType, _operator);
        return recordId;
    }

    function _statementHash(string memory _canonicalMetadata) internal pure returns (uint256) {
        return uint256(keccak256(bytes(_canonicalMetadata))) % SNARK_SCALAR_FIELD;
    }

    function statementHashOf(string calldata _canonicalMetadata) external pure returns (uint256) {
        return _statementHash(_canonicalMetadata);
    }

    function getHistoryLength(uint256 _modelId) external view returns (uint256) {
        return modelHistory[_modelId].length;
    }

    function verifyChain(uint256 _modelId) external view returns (bool) {
        uint256[] storage hist = modelHistory[_modelId];
        bytes32 prev = bytes32(0);
        for (uint256 i = 0; i < hist.length; i++) {
            ProvenanceRecord storage r = records[hist[i]];
            if (r.previousHash != prev) return false;
            bytes32 computed = keccak256(
                abi.encode(r.recordId, r.modelId, r.eventType, r.ipfsMetadata, r.timestamp, r.operator, r.previousHash)
            );
            if (computed != r.recordHash) return false;
            prev = r.recordHash;
        }
        return true;
    }
}

contracts/ZKProvenanceTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./ModelAccessControl.sol";
import "./Verifier.sol";

interface IZKModelRegistry {
    function getModelOwner(uint256 _id) external view returns (address);
    function getModelStatus(uint256 _id) external view returns (uint8);
    function isModelStaked(uint256 _id) external view returns (bool);
}

/// @title ZKProvenanceTracker
/// @notice Verifier-gated provenance tracker that preserves the original read model.
contract ZKProvenanceTracker {
    enum EventType {
        REGISTERED,
        ACTIVATED,
        UPDATED,
        DEPRECATED,
        REVOKED,
        VERSION_RELEASED,
        TRANSFERRED,
        STAKED,
        UNSTAKED,
        SLASHED,
        ZK_PROOF_VERIFIED
    }

    struct ProvenanceRecord {
        uint256 recordId;
        uint256 modelId;
        EventType eventType;
        string ipfsMetadata;
        uint256 timestamp;
        address operator;
        bytes32 previousHash;
        bytes32 recordHash;
    }

    uint256 internal constant SNARK_SCALAR_FIELD =
        21888242871839275222246405745257275088548364400416034343698204186575808495617;

    ModelAccessControl public accessControl;
    IZKModelRegistry public registry;
    Groth16Verifier public verifier;

    uint256 private _recordCounter;
    mapping(uint256 => ProvenanceRecord) public records;
    mapping(uint256 => uint256[]) public modelHistory;
    mapping(uint256 => bytes32) public modelChainHead;
    mapping(uint256 => bool) public modelBlacklist;
    mapping(uint256 => string) public blacklistReasons;
    mapping(uint256 => bool) public nullifierUsed;

    event RecordAdded(
        uint256 indexed recordId,
        uint256 indexed modelId,
        EventType indexed eventType,
        address operator
    );
    event ProofVerified(
        uint256 indexed modelId,
        address indexed operator,
        uint256 indexed nullifier,
        uint256 statementHash,
        uint256 timestamp
    );
    event ModelBlacklisted(uint256 indexed modelId, string reason, address by);
    event ModelUnblacklisted(uint256 indexed modelId, address by);

    error ModelIsBlacklisted();
    error NotAuthorized();
    error ModelNotRegistered();
    error InvalidProof();
    error InvalidModelSignal();
    error InvalidStatementHash();
    error NullifierAlreadyUsed();

    constructor(address _accessControl, address _registry, address _verifier) {
        require(_accessControl != address(0), "Tracker: access control required");
        require(_registry != address(0), "Tracker: registry required");
        require(_verifier != address(0), "Tracker: verifier required");
        accessControl = ModelAccessControl(_accessControl);
        registry = IZKModelRegistry(_registry);
        verifier = Groth16Verifier(_verifier);
    }

    function addVerifiedRecord(
        uint256 _modelId,
        EventType _eventType,
        string calldata _canonicalMetadata,
        uint[2] calldata _pA,
        uint[2][2] calldata _pB,
        uint[2] calldata _pC,
        uint[3] calldata _pubSignals
    ) external notBlacklisted returns (uint256) {
        require(
            accessControl.hasRole(accessControl.REGISTRAR(), msg.sender),
            "Tracker: requires REGISTRAR role"
        );

        _checkModelStatus(_modelId);
        if (modelBlacklist[_modelId]) revert ModelIsBlacklisted();

        if (_pubSignals[1] != _modelId) revert InvalidModelSignal();

        uint256 statementHash = _statementHash(_canonicalMetadata);
        if (_pubSignals[2] != statementHash) revert InvalidStatementHash();

        uint256 nullifier = _pubSignals[0];
        if (nullifierUsed[nullifier]) revert NullifierAlreadyUsed();

        bool verified = verifier.verifyProof(_pA, _pB, _pC, _pubSignals);
        if (!verified) revert InvalidProof();

        nullifierUsed[nullifier] = true;
        emit ProofVerified(_modelId, msg.sender, nullifier, statementHash, block.timestamp);

        return _appendRecord(_modelId, _eventType, msg.sender, _canonicalMetadata);
    }

    function blacklistModel(uint256 _modelId, string calldata _reason) external onlyAdmin {
        require(_modelId > 0, "Tracker: invalid model id");
        modelBlacklist[_modelId] = true;
        blacklistReasons[_modelId] = _reason;
        _appendRecord(_modelId, EventType.REVOKED, msg.sender, _reason);
        emit ModelBlacklisted(_modelId, _reason, msg.sender);
    }

    function unblacklistModel(uint256 _modelId) external onlyAdmin {
        require(modelBlacklist[_modelId], "Tracker: not blacklisted");
        modelBlacklist[_modelId] = false;
        delete blacklistReasons[_modelId];
        emit ModelUnblacklisted(_modelId, msg.sender);
    }

    function getModelHistory(uint256 _modelId) external view returns (ProvenanceRecord[] memory) {
        uint256[] storage ids = modelHistory[_modelId];
        ProvenanceRecord[] memory result = new ProvenanceRecord[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = records[ids[i]];
        }
        return result;
    }

    function verifyChain(uint256 _modelId) external view returns (bool) {
        uint256[] storage ids = modelHistory[_modelId];
        if (ids.length == 0) return true;

        bytes32 prevRecordHash = bytes32(0);

        for (uint256 i = 0; i < ids.length; i++) {
            ProvenanceRecord storage record = records[ids[i]];

            if (record.previousHash != prevRecordHash) {
                return false;
            }

            bytes32 computed = keccak256(
                abi.encode(
                    record.recordId,
                    record.modelId,
                    record.eventType,
                    record.ipfsMetadata,
                    record.timestamp,
                    record.operator,
                    record.previousHash
                )
            );
            if (record.recordHash != computed) {
                return false;
            }

            prevRecordHash = record.recordHash;
        }

        return true;
    }

    function getModelsStatus(uint256[] calldata _modelIds)
        external
        view
        returns (uint8[] memory statuses, bool[] memory blacklisted)
    {
        statuses = new uint8[](_modelIds.length);
        blacklisted = new bool[](_modelIds.length);
        for (uint256 i = 0; i < _modelIds.length; i++) {
            statuses[i] = registry.getModelStatus(_modelIds[i]);
            blacklisted[i] = modelBlacklist[_modelIds[i]];
        }
    }

    function computeStatementHash(string calldata _canonicalMetadata) external pure returns (uint256) {
        return _statementHash(_canonicalMetadata);
    }

    function _appendRecord(
        uint256 _modelId,
        EventType _eventType,
        address _operator,
        string memory _ipfsMetadata
    ) internal returns (uint256) {
        uint256 recordId = ++_recordCounter;
        bytes32 prevHash = modelChainHead[_modelId];

        ProvenanceRecord memory record = ProvenanceRecord({
            recordId: recordId,
            modelId: _modelId,
            eventType: _eventType,
            ipfsMetadata: _ipfsMetadata,
            timestamp: block.timestamp,
            operator: _operator,
            previousHash: prevHash,
            recordHash: bytes32(0)
        });

        record.recordHash = keccak256(
            abi.encode(
                record.recordId,
                record.modelId,
                record.eventType,
                record.ipfsMetadata,
                record.timestamp,
                record.operator,
                record.previousHash
            )
        );

        records[recordId] = record;
        modelHistory[_modelId].push(recordId);
        modelChainHead[_modelId] = record.recordHash;

        emit RecordAdded(recordId, _modelId, _eventType, _operator);
        return recordId;
    }

    function _checkModelStatus(uint256 _modelId) internal view {
        if (registry.getModelOwner(_modelId) == address(0)) revert ModelNotRegistered();
        uint8 status = registry.getModelStatus(_modelId);
        require(status != 3, "Tracker: model is revoked");
    }

    function _statementHash(string memory _canonicalMetadata) internal pure returns (uint256) {
        return uint256(keccak256(bytes(_canonicalMetadata))) % SNARK_SCALAR_FIELD;
    }

    modifier notBlacklisted() {
        if (accessControl.isBlacklisted(msg.sender)) revert NotAuthorized();
        _;
    }

    modifier onlyAdmin() {
        if (!accessControl.hasRole(accessControl.ADMIN(), msg.sender)) revert NotAuthorized();
        _;
    }
}

contracts/PassiveAnchoringTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title PassiveAnchoringTracker
/// @notice Minimal passive-anchoring baseline: writes the submitted provenance
///         payload directly into a per-model array. It performs NO statement-hash
///         recomputation, NO proof verification, NO nullifier check, and NO owner
///         binding. The ledger is used purely as an append-only store.
contract PassiveAnchoringTracker {
    struct AnchoredRecord {
        uint256 modelId;
        string modelHash;
        string artifactCid;
        string canonicalMetadata;
        address assertedOwner;
        uint256 timestamp;
    }

    uint256 private _recordCounter;
    mapping(uint256 => AnchoredRecord[]) public modelRecords;

    event RecordAnchored(uint256 indexed recordId, uint256 indexed modelId, address assertedOwner);

    function anchorRecord(
        uint256 _modelId,
        string calldata _modelHash,
        string calldata _artifactCid,
        string calldata _canonicalMetadata,
        address _assertedOwner
    ) external returns (uint256) {
        uint256 recordId = ++_recordCounter;

        modelRecords[_modelId].push(
            AnchoredRecord({
                modelId: _modelId,
                modelHash: _modelHash,
                artifactCid: _artifactCid,
                canonicalMetadata: _canonicalMetadata,
                assertedOwner: _assertedOwner,
                timestamp: block.timestamp
            })
        );

        emit RecordAnchored(recordId, _modelId, _assertedOwner);
        return recordId;
    }

    function getRecordCount(uint256 _modelId) external view returns (uint256) {
        return modelRecords[_modelId].length;
    }
}
